// =============================================
// SPI Slave Testbench - Auto-generated by SPI Customizer
// =============================================

`timescale 1ns / 1ps

module spi_slave_tb;

    // Parameters
    parameter MODE = 0;
    parameter DATA_WIDTH = 1;
    parameter NUM_SLAVES = 3;
    parameter SLAVE_ACTIVE_LOW = 1;
    parameter MSB_FIRST = 0;
    parameter FIFO_DEPTH = 16;
    parameter MAX_SLAVES = 8;
    parameter DEFAULT_DATA_ENABLED = 0;
    parameter DEFAULT_DATA_PATTERN = "ffff";
    parameter DEFAULT_DATA_VALUE = 1'hF;
    localparam SS_ACTIVE = SLAVE_ACTIVE_LOW ? 1'b0 : 1'b1;
    localparam SS_INACTIVE = ~SS_ACTIVE;

    // Signals
    reg clk;
    reg rst_n;
    reg sclk_in;
    reg mosi_in;
    wire miso_out;
    reg ss_in;
    reg [DATA_WIDTH-1:0] tx_data;
    wire [DATA_WIDTH-1:0] rx_data;
    wire rx_valid;
    wire tx_ready;
    wire busy;
    wire irq;
    integer i;
    integer timeout_cycles;
    reg [DATA_WIDTH-1:0] expected_rx;
    reg rx_valid_seen;

    // DUT instantiation
    spi_slave #(
        .MODE(MODE),
        .DATA_WIDTH(DATA_WIDTH),
        .SLAVE_ACTIVE_LOW(SLAVE_ACTIVE_LOW),
        .MSB_FIRST(MSB_FIRST),
        .FIFO_DEPTH(FIFO_DEPTH),
        .MAX_SLAVES(MAX_SLAVES),
        .DEFAULT_DATA_ENABLED(DEFAULT_DATA_ENABLED),
        .DEFAULT_DATA_PATTERN(DEFAULT_DATA_PATTERN),
        .DEFAULT_DATA_VALUE(DEFAULT_DATA_VALUE)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .sclk(sclk_in),
        .mosi(mosi_in),
        .miso(miso_out),
        .ss_n(ss_in),
        .rx_data(rx_data),
        .tx_data(tx_data),
        .rx_valid(rx_valid),
        .tx_ready(tx_ready),
        .tx_valid(tx_ready),  // Slave uses tx_ready as tx_valid input
        .busy(busy),
        .irq(irq),
        .irq_clear(1'b0)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #10 clk = ~clk;  // 50MHz clock
    end

    // Test sequence for slave mode
    initial begin
        // Initialize
        rst_n = 0;
        sclk_in = (MODE == 2 || MODE == 3) ? 1 : 0;  // CPOL idle state
        mosi_in = 0;
        ss_in = SS_INACTIVE;  // Deactivate slave select initially
        tx_data = 0;
        expected_rx = {DATA_WIDTH{1'b0}};
        rx_valid_seen = 1'b0;

        #100;
        rst_n = 1;
        #200;  // Allow system to stabilize

        $display("=== SPI Slave RTL Testbench Starting ===");
        $display("Configuration: Mode %d, %d-bit data, Slave mode", MODE, DATA_WIDTH);

        // Act as master to test the slave with deterministic payload checks.
        $display("--- Testing Slave with Deterministic Transaction ---");
        tx_data = 1'h3C;
        expected_rx = 1'hA5;
        if (MSB_FIRST)
            mosi_in = expected_rx[DATA_WIDTH - 1];
        else
            mosi_in = expected_rx[0];

        #100;
        ss_in = SS_ACTIVE;  // Select slave
        timeout_cycles = 0;
        while (!busy && timeout_cycles < 50) begin
            #20;
            timeout_cycles = timeout_cycles + 1;
        end
        if (!busy) begin
            $fatal(1, "Slave did not assert busy after selection within timeout");
        end
        #100;  // Guard window for SS/sclk synchronization before first data bit

        for (i = 0; i < DATA_WIDTH; i = i + 1) begin
            if (MSB_FIRST)
                mosi_in = expected_rx[DATA_WIDTH - 1 - i];
            else
                mosi_in = expected_rx[i];
            #100;
            sclk_in = 1; // Leading edge
            #100;
            sclk_in = 0; // Trailing edge
            #120; // Hold MOSI after trailing edge for synchronized sample stability
        end

        #100;
        ss_in = SS_INACTIVE;  // Deselect slave
        timeout_cycles = 0;
        while (busy && timeout_cycles < 50) begin
            #20;
            timeout_cycles = timeout_cycles + 1;
        end
        if (busy) begin
            $fatal(1, "Slave busy did not clear after deselection within timeout");
        end

        timeout_cycles = 0;
        while (!rx_valid_seen && timeout_cycles < 200) begin
            #20;
            timeout_cycles = timeout_cycles + 1;
        end
        if (!rx_valid_seen) begin
            $fatal(1, "Slave rx_valid did not assert within timeout");
        end
        if (rx_data !== expected_rx) begin
            $fatal(1, "Slave RX mismatch. expected=0x%h got=0x%h", expected_rx, rx_data);
        end

        $display("=== All Slave Tests Completed Successfully ===");
        $finish;
    end

    // Latch rx_valid pulse so checks are robust to single-cycle assertion.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rx_valid_seen <= 1'b0;
        else if (rx_valid)
            rx_valid_seen <= 1'b1;
    end

    // VCD dumping
    initial begin
        $dumpfile("results/issue-56/data/spi_waveform.vcd");
        $dumpvars(0, spi_slave_tb);
    end

endmodule